effect.shader:
//vec2 projectAndClamp(vec2 a, vec2 b) {
//    return clamp(dot(a,b)/dot(b,b),0.0,1.0) * b;
//}
vec2 project(vec2 a, vec2 b) {
    return (dot(a,b)/dot(b,b)) * b;
}

 vec4 newLayer( vec4 a, vec4 b) {
 return a * (1. - b.a) + b;
 }

    float smoothstepRev(float edge0, float edge1, float x) {
    if(edge0 == edge1) return step(edge0, x);
    else return smoothstep(edge0, edge1, x);
}

void main() {

    vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm.st);
    float adjStartA = startA;
    float adjEndA = endA;
    float adjFeatherA = featherA/100.0;
    float radA = angleA * 0.0174533;
    vec2 vA = normalize(vec2(cos(radA),-sin(radA)));
    float pA = dot(acLayerNorm.st-vec2(0.5,0.5), vA)+0.5;

    float p0A = smoothstepRev(adjStartA-adjFeatherA,adjStartA,pA);
    float p1A = 1. - smoothstepRev(adjEndA,adjEndA+adjFeatherA,pA);
    vec4 wipebb = (colorbg * texColor.a)*p0A*p1A;

    //////////////////////////

    float adjStart = (0.0+start)/100.0;
    float adjEnd = (100.0-start)/100.0;
    float adjFeather = 0.0/100.0;
    float rad = angle * 0.0174533;
    adjStart = (-20.0+start)/100.0;
    adjEnd = (120.0-start)/100.0;
    vec2 v = normalize(vec2(cos(rad),-sin(rad)));
    float p = dot(acLayerNorm.st-vec2(0.5,0.5), v)+0.5;
    float p0 = smoothstep(adjStart-adjFeather,adjStart,p);
    float p1 = 1. - smoothstep(adjEnd,adjEnd+adjFeather,p);
    vec4 bbmaker = texture2DCv(inputImg.texture,acScreenNorm.st)*p0*p1;

    gl_FragColor = newLayer(wipebb, bbmaker) * texColor.a;
}
